import {papers,paperLessons} from './papers-data.js';
const ext=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const credit=(l)=>{const p=papers[l.paperId];return `<div class="paper-credit">原图：${p.authors} (${p.short.split(' · ')[1]}), ${p.journal}, Fig. ${l.figure} · ${ext(p.url+'/figures/'+l.figure,'论文图页')} · ${ext('https://creativecommons.org/licenses/by/4.0/','CC BY 4.0')}<br>保留出版方图像；页面缩放与导读框由本站添加，中文讲解为本站编写。</div>`;};
export function paperReader(l){const p=papers[l.paperId];return `<div class="reader-heading"><span class="eyebrow">REAL PAPER / ${p.short}</span><h2>${l.name}</h2><p class="lesson-goal"><strong>学完你能：</strong>${l.goal}</p></div><div class="lesson-analogy"><span>带着研究问题读原文</span><p>${p.question}</p><p>${p.contribution}</p></div><div class="paper-reference"><strong>${p.title}</strong><p>${p.authors} · ${p.journal}</p><p>${ext(p.url,'阅读论文全文')} · DOI: ${p.doi}</p><small>${p.scope}</small></div><div class="paper-sample"><strong>先认清样本与分析单位</strong><p>${p.sample}</p></div><div class="lesson-sections">${l.steps.map((s,i)=>`<section><span class="lesson-number">0${i+1}</span><div><h3>${s.title} <small>Fig. ${s.panel}</small></h3><p>${s.body}</p><p><strong>读图判断：</strong>${s.takeaway}</p></div></section>`).join('')}</div><div class="paper-takeaway"><strong>把结论说完整</strong><p>${l.recap}</p>${l.evidence.map(x=>`<p>${x}</p>`).join('')}</div><div class="lesson-terms">${p.terms.map(([cn,en])=>`<span><strong>${cn}</strong><small>${en}</small></span>`).join('')}</div>${credit(l)}<div class="reader-actions"><button class="outline" data-mode="structure">回到原图导读 ↑</button><button class="primary" data-practice>完成本课 4 道练习 →</button></div>`;}

export class PaperStudio{
 constructor(root,lesson,mode){this.root=root;this.lesson=lesson;this.mode=mode;this.step=0;this.designStep=0;this.timer=null;this.zoom=1;this.x=0;this.y=0;this.drag=null;this.abort=new AbortController();const opts={signal:this.abort.signal};root.addEventListener('click',e=>this.click(e),opts);root.addEventListener('input',e=>{if(e.target.matches('[data-paper-zoom]'))this.setZoom(+e.target.value);},opts);root.addEventListener('keydown',e=>this.key(e),opts);root.addEventListener('pointerdown',e=>this.down(e),opts);root.addEventListener('pointermove',e=>this.move(e),opts);root.addEventListener('pointerup',()=>this.drag=null,opts);root.addEventListener('pointercancel',()=>this.drag=null,opts);this.render();}
 destroy(){this.pause();this.resize?.disconnect();this.abort.abort();this.root.querySelector('[data-paper-viewport]')?.classList.remove('paper-dragging');}
 pause(){clearInterval(this.timer);this.timer=null;}
 getState(){return {topic:this.lesson.id,mode:this.mode,step:this.step,designStep:this.designStep,zoom:this.zoom,playing:!!this.timer,x:this.x,y:this.y};}
 click(e){const b=e.target.closest('button');if(!b)return;
 if(b.dataset.paperStep!==undefined){this.pause();this.step=+b.dataset.paperStep;this.render(true);}
 if(b.dataset.paperNext!==undefined){this.pause();this.step=Math.max(0,Math.min(3,this.step+(+b.dataset.paperNext)));this.render(true);}
 if(b.hasAttribute('data-paper-fit')){this.reset();}
 if(b.hasAttribute('data-paper-focus')){this.focus();}
 if(b.dataset.paperScale){this.setZoom(this.zoom+(+b.dataset.paperScale));}
 if(b.dataset.paperDesign!==undefined){this.designStep=+b.dataset.paperDesign;this.render();}
 if(b.hasAttribute('data-paper-play')){if(this.timer)this.pause();else{if(this.step===3)this.step=0;this.timer=setInterval(()=>{this.step++;if(this.step===3)this.pause();this.render(true);},10000);}this.render(true);}
 }
 render(focus=false){this.resize?.disconnect();const l=this.lesson,p=papers[l.paperId];this.root.innerHTML=`<div class="paper-studio"><header><span class="eyebrow">${p.short} / ORIGINAL FIGURE ${l.figure}</span><h2>${l.name}</h2><p>${l.goal}</p><div class="paper-badges"><span>真实论文 · 原图</span><span>中文逐步导读</span><span>本课 4 道练习</span></div></header>${this.mode==='process'?this.design():this.mode==='connections'?this.recap():this.figure()}</div>`;
 if(this.mode==='structure'){this.viewport=this.root.querySelector('[data-paper-viewport]');this.layer=this.root.querySelector('[data-paper-layer]');this.img=this.layer.querySelector('img');this.img.addEventListener('load',()=>this.measure(focus),{once:true,signal:this.abort.signal});this.img.addEventListener('error',()=>{this.root.querySelector('[data-paper-error]').hidden=false;},{once:true,signal:this.abort.signal});if(this.img.complete&&this.img.naturalWidth)this.measure(focus);this.resize=new ResizeObserver(()=>this.measure(focus));this.resize.observe(this.viewport);}
 }
 figure(){const l=this.lesson,s=l.steps[this.step];return `<div class="paper-guide-nav" aria-label="原图导读步骤">${l.steps.map((s,i)=>`<button data-paper-step="${i}" aria-pressed="${i===this.step}"><small>0${i+1} · Fig. ${s.panel}</small><strong>${s.title}</strong></button>`).join('')}</div><div class="paper-guide" aria-live="polite"><span>正在读 Fig. ${s.panel}</span><h3>${s.title}</h3><p>${s.body}</p><div class="paper-guide-tip">${s.takeaway}</div></div><div class="paper-guide-actions"><button class="outline" data-paper-next="-1" ${this.step===0?'disabled':''}>← 上一步</button><button class="outline" data-paper-next="1" ${this.step===3?'disabled':''}>下一步 →</button><button class="outline" data-paper-play>${this.timer?'暂停导读':'自动导读 · 每步 10 秒'}</button></div><div class="paper-toolbar"><button class="outline" data-paper-fit>看整张图</button><button class="outline" data-paper-focus>定位当前面板</button><div class="paper-zoom"><button data-paper-scale="-.5" aria-label="缩小论文原图">−</button><label>缩放 <output data-paper-output>100%</output><input data-paper-zoom type="range" min="1" max="6" step=".1" value="1" aria-label="论文原图缩放"></label><button data-paper-scale=".5" aria-label="放大论文原图">＋</button></div></div><div class="paper-viewport" data-paper-viewport tabindex="0" role="region" aria-label="论文原图查看器，可拖动平移，方向键平移，加减键缩放，0 键复位"><div class="paper-image-layer" data-paper-layer><img src="${l.asset}" alt="${papers[l.paperId].short} 原论文 Fig. ${l.figure}。各面板的中文说明见上方四个导读步骤。" draggable="false"><div class="paper-focus-box" data-paper-box hidden aria-hidden="true"></div></div></div><p class="paper-error" data-paper-error hidden>原图未能载入，请刷新重试，或打开下方论文图页；中文讲解仍可阅读。</p><p class="paper-help">放大后拖动或用方向键平移；＋／− 缩放，0 复位。蓝灰框仅标记当前导读区域。</p>${credit(l)}`;}
 design(){const p=papers[this.lesson.paperId],s=p.design[this.designStep];return `<div class="paper-question"><small>研究问题</small><h3>${p.question}</h3><p>${p.contribution}</p></div><div class="paper-design-path">${p.design.map((x,i)=>`<button data-paper-design="${i}" aria-pressed="${i===this.designStep}"><b>0${i+1}</b><span>${x[0]}</span><small>${i<3?'↓':'✓'}</small></button>`).join('')}</div><section class="paper-design-detail" aria-live="polite"><span>实验环节 ${this.designStep+1} / 4</span><h3>${s[0]}</h3><p>${s[1]}</p><small>证据定位：${s[2]}</small></section><div class="paper-sample"><strong>样本账本</strong><p>${p.sample}</p></div><div class="paper-comparison"><h3>这几类信息各回答什么？</h3>${(this.lesson.paperId==='zheng'?[['细胞条码','这份表达信号归属于哪个细胞相关条码？'],['UMI','同一细胞、同一基因的读段中，哪些可能是扩增重复？'],['样本索引','这条读段来自哪个混合测序的文库？']]:[['RNA 表达','细胞现在的类型与状态是什么？'],['cloneID','哪些细胞继承了共同的谱系标签？'],['空间条码 + 图像配准','分子信号落在组织哪个捕获位置？'],['蛋白免疫染色','被标记细胞是否具有所测类型标记？']]).map(([a,b])=>`<div><strong>${a}</strong><p>${b}</p></div>`).join('')}</div><p class="paper-credit">${ext(p.url,'对照原文 Methods 与图注')}</p><button class="outline" data-mode="structure">带着实验设计回到原图 →</button>`;}
 recap(){const l=this.lesson,p=papers[l.paperId];return `<div class="paper-question"><small>从图到结论</small><h3>${l.recap}</h3></div><div class="paper-evidence">${l.evidence.map((x,i)=>`<section><span>${i?'解释时保留的条件':'这张图提供的证据'}</span><p>${x}</p></section>`).join('')}</div><div class="paper-write"><h3>用三句话复述这张图</h3><ol><li>研究者想回答什么？取材对象和比较对象是什么？</li><li>我在 Fig. ${l.figure} 的哪个面板看到什么趋势？点、颜色和分母各指什么？</li><li>这项观察支持什么结论？哪一步还需要其他证据？</li></ol><p>点击右侧“用自己的话记一笔”，把答案保存到本课笔记。</p><button class="primary" data-practice>用 4 道练习检查理解 →</button></div><h3 class="paper-more-title">沿着同一研究继续读</h3><div class="paper-directory">${paperLessons.filter(x=>x.paperId===p.id).map(x=>`<button data-jump="${x.id}" ${x.id===l.id?'aria-current="step"':''}><small>Fig. ${x.figure}</small><strong>${x.name}</strong><span>→</span></button>`).join('')}</div><p class="paper-credit">${ext(p.url,p.short+' · 论文全文')}</p>`;}
 measure(focus){if(!this.img?.naturalWidth||!this.viewport?.isConnected)return;const w=this.viewport.clientWidth,h=this.viewport.clientHeight;this.baseW=Math.min(w,h*this.img.naturalWidth/this.img.naturalHeight);this.baseH=this.baseW*this.img.naturalHeight/this.img.naturalWidth;this.layer.style.width=this.baseW+'px';this.layer.style.height=this.baseH+'px';if(focus)this.focus();else this.reset();}
 reset(){this.zoom=1;this.x=(this.viewport.clientWidth-this.baseW)/2;this.y=(this.viewport.clientHeight-this.baseH)/2;this.root.querySelector('[data-paper-box]').hidden=true;this.paint();}
 focus(){if(!this.baseW)return;const [x,y,w,h]=this.lesson.steps[this.step].focus;this.zoom=Math.max(1,Math.min(6,Math.min(this.viewport.clientWidth/(this.baseW*w),this.viewport.clientHeight/(this.baseH*h))*.94));this.x=this.viewport.clientWidth/2-(x+w/2)*this.baseW*this.zoom;this.y=this.viewport.clientHeight/2-(y+h/2)*this.baseH*this.zoom;const box=this.root.querySelector('[data-paper-box]');Object.assign(box.style,{left:x*100+'%',top:y*100+'%',width:w*100+'%',height:h*100+'%'});box.hidden=false;this.paint();}
 setZoom(value){if(!this.baseW)return;const z=Math.max(1,Math.min(6,value)),ratio=z/this.zoom,w=this.viewport.clientWidth/2,h=this.viewport.clientHeight/2;this.x=w-(w-this.x)*ratio;this.y=h-(h-this.y)*ratio;this.zoom=z;this.paint();}
 paint(){if(!this.baseW)return;const w=this.viewport.clientWidth,h=this.viewport.clientHeight,sw=this.baseW*this.zoom,sh=this.baseH*this.zoom;this.x=sw<=w?(w-sw)/2:Math.min(0,Math.max(w-sw,this.x));this.y=sh<=h?(h-sh)/2:Math.min(0,Math.max(h-sh,this.y));this.layer.style.transform=`translate(${this.x}px,${this.y}px) scale(${this.zoom})`;this.root.querySelector('[data-paper-zoom]').value=this.zoom;this.root.querySelector('[data-paper-output]').value=Math.round(this.zoom*100)+'%';}
 down(e){if(!e.target.closest('[data-paper-viewport]')||e.button!==0||!this.baseW)return;this.viewport.focus({preventScroll:true});this.viewport.setPointerCapture(e.pointerId);this.drag={x:e.clientX,y:e.clientY,left:this.x,top:this.y};}
 move(e){if(!this.drag)return;this.x=this.drag.left+e.clientX-this.drag.x;this.y=this.drag.top+e.clientY-this.drag.y;this.paint();}
 key(e){if(!e.target.matches('[data-paper-viewport]'))return;const delta={ArrowLeft:[40,0],ArrowRight:[-40,0],ArrowUp:[0,40],ArrowDown:[0,-40]}[e.key];if(delta){e.preventDefault();this.x+=delta[0];this.y+=delta[1];this.paint();}else if(['+','=','-','0'].includes(e.key)){e.preventDefault();if(e.key==='0')this.reset();else this.setZoom(this.zoom+(e.key==='-'?-.5:.5));}}
}
